import sys
from collections.abc import Sequence

from bubble_sort.core import bubble_sort

DEMO_VALUES = (64, 34, 25, 12, 22, 11, 90)
ParsedValues = list[int] | list[str]

__all__ = ["DEMO_VALUES", "format_values", "main", "parse_values", "sorted_values"]


def parse_values(arguments: Sequence[str]) -> ParsedValues:
    if not arguments:
        return list(DEMO_VALUES)

    integers = _parse_integer_arguments(arguments)
    if integers is not None:
        return integers

    return list(arguments)


def _parse_integer_arguments(arguments: Sequence[str]) -> list[int] | None:
    try:
        return [int(argument) for argument in arguments]
    except ValueError:
        return None


def sorted_values(arguments: Sequence[str]) -> ParsedValues:
    values = parse_values(arguments)
    bubble_sort(values)
    return values


def format_values(values: ParsedValues) -> str:
    return str(values)


def main(argv: Sequence[str] | None = None) -> None:
    arguments = sys.argv[1:] if argv is None else argv
    print(format_values(sorted_values(arguments)))

from collections.abc import MutableSequence
from typing import Any, Protocol, TypeVar


class _SupportsGreaterThan(Protocol):
    def __gt__(self, other: Any) -> bool:
        ...


_Sortable = TypeVar("_Sortable", bound=_SupportsGreaterThan)

__all__ = ["bubbleSort", "bubble_sort"]


def bubble_sort(values: MutableSequence[_Sortable]) -> None:
    """Sort values in ascending order in place using bubble sort."""
    unsorted_limit = len(values) - 1

    while unsorted_limit > 0:
        last_swap_index: int | None = None

        for index in range(unsorted_limit):
            if values[index] > values[index + 1]:
                values[index], values[index + 1] = values[index + 1], values[index]
                last_swap_index = index

        if last_swap_index is None:
            break

        unsorted_limit = last_swap_index


def bubbleSort(values: MutableSequence[_Sortable]) -> None:
    """Compatibility wrapper for callers using the original camelCase name."""
    bubble_sort(values)
